#include <cstdio>
#include <algorithm>

using namespace std;

const int N = 3005;
const long long oo = 1e18;

int n, k;
int a[N], l[N], r[N], d[N];
long long ans;

void solve() {
	scanf("%d%d", &n, &k);
	for (int i = 1; i <= n; i++)
		scanf("%d", &a[i]);
	ans = oo;
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= k; j++)
			l[j] = r[j] = n + 1;
		for (int j = i; j; j--)
			l[a[j]] = min(l[a[j]], i - j);
		for (int j = i; j <= n; j++)
			r[a[j]] = min(r[a[j]], j - i);
		long long s = 0;
		for (int j = 1; j <= k; j++) {
			s += l[j];
			d[j] = r[j] - l[j];
		}
		sort(d + 1, d + k + 1);
		for (int j = 1; j <= (k + 1) / 2; j++)
			s += d[j];
		ans = min(ans, s);
	}
	for (int i = 1; i <= k; i++)
		ans -= abs(i - (k + 1) / 2);
	printf("%lld\n", ans);
}

int main() {
	int T;
	scanf("%d", &T);
	while (T--)
		solve();
	return 0;
}
